                ) : (
                    <div className="flex flex-col gap-3">
                        {filtered.map((regulation) => (
                            <AlertCard key={regulation.id} regulation={regulation} />
                        ))}
                    </div>
                )}
            </div>
        </AppLayout>
    );
}

