import { Head, Link, router } from '@inertiajs/react';
import { AlertTriangle, Bell, CheckCircle2, Info, ShieldAlert } from 'lucide-react';
import { useState } from 'react';
import AppLayout from '@/layouts/app-layout';
import type { BreadcrumbItem } from '@/types';

interface Regulation {
    id: number;
    type: string;
    severity: 'urgent' | 'warning' | 'info';
    title: string;
    description: string;
    action_label: string | null;
    action_url: string | null;
    due_date: string | null;
    is_read: boolean;
    is_resolved: boolean;
    created_at: string;
}

interface Props {
    regulations: Regulation[];
}

const breadcrumbs: BreadcrumbItem[] = [
    { title: 'Mi Explotación', href: '/dashboard' },
    { title: 'Normativa', href: '/normativa' },
];

const severityConfig = {
    urgent: {
        icon: ShieldAlert,
        label: 'Urgente',
        badgeBg: 'bg-[#E53935]',
        badgeText: 'text-white',
        borderColor: 'border-l-[#E53935]',
        countBg: 'bg-[#E53935]',
    },
    warning: {
        icon: AlertTriangle,
        label: 'Atención',
        badgeBg: 'bg-[#FFF3E0]',
        badgeText: 'text-[#E65100]',
        borderColor: 'border-l-[#E65100]',
        countBg: 'bg-[#E65100]',
    },
    info: {
        icon: Info,
        label: 'Información',
        badgeBg: 'bg-[#E3F2FD]',
        badgeText: 'text-[#1565C0]',
        borderColor: 'border-l-[#1565C0]',
        countBg: 'bg-[#1565C0]',
    },
};

function timeAgo(dateString: string): string {
    const now = new Date();
    const date = new Date(dateString);
    const diffMs = now.getTime() - date.getTime();
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffHours / 24);

    if (diffHours < 1) return 'hace un momento';
    if (diffHours < 24) return `hace ${diffHours}h`;
    if (diffDays === 1) return 'ayer';
    return `hace ${diffDays} días`;
}

function daysUntil(dateString: string): string | null {
    const now = new Date();
    const date = new Date(dateString);
    const diffMs = date.getTime() - now.getTime();
    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

    if (days < 0) return 'Vencido';
    if (days === 0) return 'Hoy';
    if (days === 1) return 'Mañana';
    return `Quedan ${days} días`;
}

function AlertCard({ regulation }: { regulation: Regulation }) {
    const config = severityConfig[regulation.severity];
    const Icon = config.icon;

    const markRead = () => {
        if (!regulation.is_read) {
            router.patch(`/api/regulations/${regulation.id}/read`, {}, { preserveScroll: true });
        }
    };

    const markResolved = () => {
        router.patch(`/api/regulations/${regulation.id}/resolve`, {}, { preserveScroll: true });
    };

    return (
        <div
            className={`border-2 border-black border-l-4 ${config.borderColor} ${!regulation.is_read ? 'bg-[#FAFAFA]' : 'bg-white'} w-full`}
            onClick={markRead}
        >
            <div className="flex flex-col gap-3 p-4">
                <div className="flex items-center justify-between">
                    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 text-xs font-bold ${config.badgeBg} ${config.badgeText}`}>
                        <Icon className="size-3" />
                        {config.label}
